    data('retrogradeTrackArtwork',settings.trackArtwork);data('retrogradeLibrary',settings.libraryStyle);token('--rp-lyrics-size',settings.lyricsSize+'px');
    for(const k of P.colorKeys) token('--rp-'+k,settings[k]);
